mod support;
use sha2::{Digest,Sha256};use tokio_util::sync::CancellationToken;
use video_kadr_backend::{services::{concat_video_analysis::{RunCache,PublishedCache,import_checkpoint},concat_video_checkpoint::Expected},handlers::concat_video_cache as registry};
const MODEL:&str="3241ac4ad8aa35bdaf33946776db29f7c283a413aa0b0dacb9483594b4531aad";
fn digest(bytes:&[u8])->String{format!("{:x}",Sha256::digest(bytes))}
fn directory(path:&std::path::Path){std::fs::create_dir(path).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700)).unwrap();}}
fn file(path:&std::path::Path,bytes:&[u8]){std::fs::write(path,bytes).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o600)).unwrap();}}
#[tokio::test]
async fn project_generations_append_only_new_masks_and_preserve_failed_commit_cursor(){run(false).await;}
#[tokio::test]
async fn logical_slots_keep_independent_caches_over_one_physical_source(){run(true).await;}
async fn run(logical:bool){
 let slot=if logical{"slot"}else{"raw"};
 let(state,_state_dir)=support::make_state(true,false).await;let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(state.storage.join("app.db"))).await.unwrap();let encoded=b"procedural source identity, not a codec fixture";file(&state.storage.join("sources/raw.mkv"),encoded);assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&serde_json::json!({"id":"raw","filename":"raw.mkv","url":"/files/sources/raw.mkv","mediaType":"video","width":1,"height":1}))).await);let space=state.db.create_space("owner","Incremental registry").await.unwrap();let mut composition=video_kadr_backend::domain::composition::Composition::new(Default::default());let descriptor:video_kadr_backend::domain::composition::CompositionSource=serde_json::from_value(serde_json::json!({"id":"raw","kind":"video","durationTicks":6500000,"width":1,"height":1,"hasAudio":false})).unwrap();composition.sources.insert(descriptor.id.clone(),descriptor);let document=if logical{
  let mut descriptor=serde_json::to_value(composition.sources.values().next().unwrap()).unwrap();descriptor["id"]=serde_json::json!("slot");
  let mut alias=descriptor.clone();alias["id"]=serde_json::json!("alias");
  let mut content=serde_json::to_value(&composition).unwrap();content["sources"]=serde_json::json!({"slot":descriptor,"alias":alias});
  serde_json::json!({"schemaVersion":1,"root":"main","compositions":{"main":{"content":content,"instances":[]}},"projectMedia":{"slot":{"source":descriptor,"librarySourceId":"raw","name":"First","placeholder":false},"alias":{"source":alias,"librarySourceId":"raw","name":"Second","placeholder":false}}})
 }else{serde_json::to_value(composition).unwrap()};
 let project=state.db.create_space_composition_project("Incremental",&document,&["raw".into()],"owner",&space.id).await.unwrap();
 let root=tempfile::tempdir().unwrap();let checkpoints=root.path().join("checkpoints");directory(&checkpoints);let pixels=[11u8,22,33,255];let sequence=digest(&pixels.repeat(65));let video=digest(encoded);let runtime="b".repeat(64);let mask=vec![0u8;256*256];let cancel=CancellationToken::new();
 for ordinal in 0..65{let path=checkpoints.join(ordinal.to_string());directory(&path);file(&path.join("frame.rgba"),&pixels);file(&path.join("mask.raw"),&mask);let receipt=serde_json::json!({"schemaVersion":1,"ordinal":ordinal,"context":{"sourceHash":sequence,"frameHash":digest(&pixels),"modelHash":MODEL,"runtimeHash":runtime,"width":1,"height":1,"maskWidth":256,"maskHeight":256,"total":65},"outputHash":digest(&pixels),"maskHash":digest(&mask),"blank":true});file(&path.join("receipt.json"),&serde_json::to_vec(&receipt).unwrap());}
 let expected=|ordinal|Expected{sequence_hash:&sequence,model_hash:MODEL,runtime_hash:&runtime,source_frame:&pixels,width:1,height:1,ordinal,total:65};let mut cache=RunCache::new_for_model(video.clone(),runtime.clone(),MODEL.into()).unwrap();let mut generations:Vec<(String,String)>=vec![];let mut manifests=vec![];let published_root=state.storage.join("concat-video-caches");
 for ordinal in 0..64{
  cache.insert(import_checkpoint(&checkpoints,expected(ordinal),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.unwrap()).unwrap();if ordinal==0{
   let session=registry::PublicationSession::begin(&state,"owner",&project.id,slot,project.revision,&cache,&cancel).await.unwrap();sqlx::query("CREATE TRIGGER reject_video_choice BEFORE INSERT ON concat_video_model_choices BEGIN SELECT RAISE(ABORT,'controlled choice rejection'); END").execute(&pool).await.unwrap();assert!(session.append(&state,&mut cache,&cancel).await.is_err());let rows:i64=sqlx::query_scalar("SELECT COUNT(*) FROM concat_video_project_caches WHERE project_id=?").bind(&project.id).fetch_one(&pool).await.unwrap();assert_eq!(rows,0);assert_eq!(std::fs::read_dir(&published_root).unwrap().count(),0);sqlx::query("DROP TRIGGER reject_video_choice").execute(&pool).await.unwrap();
  }
  let id=registry::publish(&state,"owner",&project.id,slot,project.revision,&mut cache,&cancel).await.unwrap();let(generation,hash):(String,String)=sqlx::query_as("SELECT generation,manifest_hash FROM concat_video_project_caches WHERE id=?").bind(id).fetch_one(&pool).await.unwrap();let path=published_root.join(&generation);let bytes=std::fs::read(path.join("manifest.json")).unwrap();assert_eq!(digest(&bytes),hash);let manifest:serde_json::Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(manifest["runs"].as_array().unwrap().len(),1);assert_eq!(std::fs::read_dir(&path).unwrap().count(),2);assert_eq!(std::fs::metadata(path.join("0.masks")).unwrap().len(),mask.len()as u64);
  if ordinal==0{assert_eq!(manifest["schemaVersion"],1);assert!(manifest.get("parent").is_none());}else{assert_eq!(manifest["schemaVersion"],2);assert_eq!(manifest["totalRuns"],ordinal+1);assert_eq!(manifest["parent"]["generation"],generations.last().unwrap().0);assert_eq!(manifest["parent"]["manifestHash"],generations.last().unwrap().1);}
  if logical && ordinal==0{
   registry::remember_choice(&state,"owner",&project.id,slot,project.revision,&cache,&cancel).await.unwrap();
   assert!(registry::choice(&state,"owner",&project.id,slot,project.revision,&cancel).await.unwrap().is_some());
   assert!(registry::choice(&state,"owner",&project.id,"alias",project.revision,&cancel).await.unwrap().is_none());
   assert!(registry::restore_for_model(&state,"owner",&project.id,"alias",project.revision,&runtime,MODEL,&cancel).await.unwrap().is_none());
   assert!(registry::choice(&state,"outsider",&project.id,slot,project.revision,&cancel).await.is_err());
   assert!(registry::choice(&state,"owner",&project.id,slot,project.revision+1,&cancel).await.is_err());
  }
  generations.push((generation,hash));manifests.push(bytes);
 }
 let before=cache.identity().unwrap();drop(cache);let mut reopened=state.clone();reopened.db=std::sync::Arc::new(video_kadr_backend::db::Db::open(&state.storage).await.unwrap());let mut restored=registry::restore_for_model(&reopened,"owner",&project.id,slot,project.revision,&runtime,MODEL,&cancel).await.unwrap().unwrap();assert_eq!(restored.identity().unwrap(),before);for ordinal in 0..64{assert!(restored.automatic(ordinal*100,&cancel).unwrap().is_none());}
 restored.insert(import_checkpoint(&checkpoints,expected(64),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.unwrap()).unwrap();
 sqlx::query("CREATE TRIGGER reject_video_generation BEFORE INSERT ON concat_video_project_caches BEGIN SELECT RAISE(ABORT,'controlled generation rejection'); END").execute(&pool).await.unwrap();assert!(registry::publish(&state,"owner",&project.id,slot,project.revision,&mut restored,&cancel).await.is_err());assert_eq!(std::fs::read_dir(&published_root).unwrap().count(),64);sqlx::query("DROP TRIGGER reject_video_generation").execute(&pool).await.unwrap();
 let id=registry::publish(&state,"owner",&project.id,slot,project.revision,&mut restored,&cancel).await.unwrap();let(generation,hash):(String,String)=sqlx::query_as("SELECT generation,manifest_hash FROM concat_video_project_caches WHERE id=?").bind(id).fetch_one(&pool).await.unwrap();let latest=published_root.join(&generation);let latest_bytes=std::fs::read(latest.join("manifest.json")).unwrap();let manifest:serde_json::Value=serde_json::from_slice(&latest_bytes).unwrap();assert_eq!(manifest["totalRuns"],65);assert_eq!(manifest["runs"].as_array().unwrap().len(),1);assert_eq!(manifest["parent"]["generation"],generations.last().unwrap().0);let identity=restored.identity().unwrap();drop(restored);drop(root);
 for((generation,_),bytes)in generations.iter().zip(&manifests){assert_eq!(std::fs::read(published_root.join(generation).join("manifest.json")).unwrap(),*bytes);}
 let mut restored=registry::restore_for_model(&reopened,"owner",&project.id,slot,project.revision,&runtime,MODEL,&cancel).await.unwrap().unwrap();assert_eq!(restored.identity().unwrap(),identity);assert!(restored.timeline().unwrap().missing_runs(&[(0.,6.4)]).unwrap().is_empty());assert!(restored.automatic(6400,&cancel).unwrap().is_none());drop(restored);
 let receipt=PublishedCache{directory:latest.clone(),manifest_hash:hash,model_hash:MODEL.into(),video_hash:video,runtime_hash:runtime};
 let total_bytes=std::fs::read_dir(&published_root).unwrap().map(|entry|std::fs::read_dir(entry.unwrap().path()).unwrap().map(|file|file.unwrap().metadata().unwrap().len()).sum::<u64>()).sum::<u64>();assert_eq!(std::fs::read_dir(&published_root).unwrap().count(),65);let mask_bytes=65*mask.len()as u64;assert!(total_bytes>=mask_bytes&&total_bytes<mask_bytes+128*1024);assert!(RunCache::restore(&receipt,total_bytes-1,&cancel).await.is_err());
 let first=published_root.join(&generations[0].0);let original=std::fs::read(first.join("0.masks")).unwrap();let mut changed=original.clone();changed[0]=255;file(&first.join("0.masks"),&changed);assert!(RunCache::restore(&receipt,total_bytes,&cancel).await.is_err());file(&first.join("0.masks"),&original);file(&first.join("manifest.json"),b"{}");assert!(RunCache::restore(&receipt,total_bytes,&cancel).await.is_err());file(&first.join("manifest.json"),&manifests[0]);
 for parent in ["../escape".to_owned(),generation.clone()]{let mut forged=manifest.clone();forged["parent"]["generation"]=serde_json::json!(parent);let bytes=serde_json::to_vec(&forged).unwrap();file(&latest.join("manifest.json"),&bytes);let forged_receipt=PublishedCache{manifest_hash:digest(&bytes),..receipt.clone()};assert!(RunCache::restore(&forged_receipt,total_bytes+1024,&cancel).await.is_err());}
 file(&latest.join("manifest.json"),&latest_bytes);assert_eq!(RunCache::restore(&receipt,total_bytes,&cancel).await.unwrap().identity().unwrap(),identity);let mut restored=RunCache::restore(&receipt,total_bytes,&cancel).await.unwrap();let session=registry::PublicationSession::begin(&state,"owner",&project.id,slot,project.revision,&restored,&cancel).await.unwrap();file(&state.storage.join("sources/raw.mkv"),b"changed encoded-source content");session.append(&state,&mut restored,&cancel).await.unwrap();assert!(session.finish(&state,&restored,&cancel).await.is_err());assert!(registry::restore_for_model(&state,"owner",&project.id,slot,project.revision,restored.runtime_hash(),MODEL,&cancel).await.unwrap().is_none());file(&state.storage.join("sources/raw.mkv"),encoded);session.finish(&state,&restored,&cancel).await.unwrap();let count=std::fs::read_dir(&published_root).unwrap().count();sqlx::query("UPDATE composition_project_members SET role='viewer' WHERE project_id=? AND actor='owner'").bind(&project.id).execute(&pool).await.unwrap();assert!(session.append(&state,&mut restored,&cancel).await.is_err());assert_eq!(std::fs::read_dir(&published_root).unwrap().count(),count);
 eprintln!("65 generations copied exactly{mask_bytes} mask bytes; parent manifests unchanged; failed registration retried safely");
}
